function minimumRounds(tasks) {
  const freq = new Map();
  for (const task of tasks) {
    freq.set(task, (freq.get(task) || 0) + 1);
  }

  let rounds = 0;
  for (const count of freq.values()) {
    if (count === 1) {
      return -1;
    }
    rounds += Math.ceil(count / 3);
  }
  return rounds;
}

