function minimumRounds(tasks) {
  // Sort, measure each run of equal levels, and solve each run with a small DP over steps of 2 and 3.
  const sorted = [...tasks].sort((a, b) => a - b);
  const best = [0, Infinity];
  for (let c = 2; c <= sorted.length; c++) best[c] = Math.min(best[c - 2], c >= 3 ? best[c - 3] : Infinity) + 1;
  let total = 0;
  let i = 0;
  while (i < sorted.length) {
    let j = i;
    while (j < sorted.length && sorted[j] === sorted[i]) j++;
    const need = best[j - i];
    if (need === Infinity) return -1;
    total += need;
    i = j;
  }
  return total;
}

