function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 10);
    const pool = rand() < 0.5 ? 2 : 4;
    const big = rand() < 0.2;
    return [Array.from({ length: n }, () => (big ? 1000000000 - int(0, pool - 1) : int(1, pool)))];
  }
  // Build groups of equal levels; usually every group has at least two tasks.
  const n = int(1800, 2000);
  const lonely = rand() < 0.25;
  const tasks = [];
  const used = new Set();
  while (tasks.length < n) {
    let level = int(1, 1000000000);
    while (used.has(level)) level = int(1, 1000000000);
    used.add(level);
    let groupSize = int(2, rand() < 0.3 ? 200 : 12);
    if (lonely && used.size === 7) groupSize = 1;
    if (tasks.length + groupSize > n) groupSize = n - tasks.length;
    if (groupSize === 1 && !lonely && tasks.length > 0) { tasks.push(tasks[tasks.length - 1]); continue; }
    for (let k = 0; k < groupSize; k++) tasks.push(level);
  }
  for (let i = tasks.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const tmp = tasks[i]; tasks[i] = tasks[j]; tasks[j] = tmp;
  }
  return [tasks];
}
